/*Table structure for table `owner` */

DROP TABLE IF EXISTS `owner`;

CREATE TABLE `owner` (
  `owner_id` bigint(20) NOT NULL COMMENT '业主id',
  `owner_nickname` varchar(30) DEFAULT NULL COMMENT '昵称',
  `owner_real_name` varchar(30) DEFAULT NULL COMMENT '真实姓名',
  `owner_gender` varchar(10) DEFAULT NULL COMMENT '性别unknow未知male男female女',
  `owner_age` int(3) DEFAULT NULL COMMENT '年龄',
  `owner_id_card` varchar(20) DEFAULT NULL COMMENT '身份证号码',
  `owner_phone_number` varchar(11) DEFAULT NULL COMMENT '手机号码',
  `owner_open_id` varchar(64) DEFAULT NULL COMMENT 'openid',
  `owner_wechat_id` varchar(64) DEFAULT NULL COMMENT '微信号',
  `owner_qq_number` varchar(20) DEFAULT NULL COMMENT 'qq号码',
  `owner_birthday` date DEFAULT NULL COMMENT '出生日期',
  `owner_portrait` varchar(256) DEFAULT NULL COMMENT '头像',
  `owner_signature` varchar(64) DEFAULT NULL COMMENT '个性签名',
  `owner_status` varchar(10) DEFAULT NULL COMMENT '禁用状态enable启用-disable禁用',
  `owner_logon_mode` varchar(10) DEFAULT NULL COMMENT '注册方式（weChat微信-app-web）',
  `owner_type` varchar(32) DEFAULT NULL COMMENT '业主类型',
  `owner_password` varchar(128) DEFAULT NULL COMMENT '密码',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`owner_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='业主 ';

